sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// create a glide record to find user
	var guy = new GlideRecord('sys_user');
	guy.get(current.contractor);
	guy.active = false;
	guy.locked_out = true;
	guy.update();
	//This business rule actions turn account disabled to true
})(current, previous);
